			this.#database,
			"UPDATE lineages SET pruned_through_author_sequence=? WHERE object_id=? AND author=? AND next=? AND exhausted=? AND ((pruned_through_author_sequence IS NULL AND ? IS NULL) OR pruned_through_author_sequence=?)"
		).run(
